// Headless rules tests: the port against the reference TEG 0.13.0 server (test/golden/oracle.json,
// generated by re/teg/oracle/transcripts.py). The golden file holds the server's country
// distribution, secret missions, dice and countries after attacks; the same commands are replayed
// through the TypeScript engine here.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { TegGame, cardsForExchange, canTradeCards } from '../src/rules/engine.ts';
import { GlibcRand } from '../src/rules/rng.ts';
import { COUNTRIES, COUNTRY_COUNT, missionName } from '../src/rules/data.ts';
import { Robot } from '../src/rules/ai.ts';

interface Assignment { seed: number; players: number; owners: number[]; turn: number }
interface MissionCase extends Assignment { missions: number[] }
interface Dice { src: number; srcDice: number[]; dst: number; dstDice: number[] }
interface Attack {
  dice: Dice;
  countries: Record<string, [number, number]>;
  conquest: boolean;
  tropas: number | null;
}
interface AttackRun {
  seed: number; armies: [number, number]; turn: number; src: number; dst: number;
  owners: number[]; placements: { seat: number; phase: string; country: number; armies: number }[];
  attacks: Attack[];
  card?: { country: number; used: boolean };
  enumCards?: string;
}
interface Oracle {
  source: string;
  assignments: Assignment[];
  missions: MissionCase[];
  attacks: AttackRun[];
}

const oracle: Oracle = JSON.parse(readFileSync(fileURLToPath(new URL('./golden/oracle.json', import.meta.url)), 'utf8'));

function setups(n: number) {
  return Array.from({ length: n }, (_, i) => ({ name: String.fromCharCode(65 + i), color: i, human: true }));
}

test('glibc rand: the values the original server gets', () => {
  const r = new GlibcRand(12345);
  assert.deepEqual(Array.from({ length: 10 }, () => r.next()), [
    383100999, 858300821, 357768173, 455528251, 133005921, 116285904, 591987137, 102557902,
    689413528, 585691128,
  ]);
  const r1 = new GlibcRand(1);
  assert.deepEqual(Array.from({ length: 4 }, () => r1.next()), [1804289383, 846930886, 1681692777, 1714636915]);
});

test('country distribution and first player: the original server for each seed', () => {
  for (const a of oracle.assignments) {
    const g = TegGame.create(a.seed, setups(a.players));
    const owners = Array.from({ length: COUNTRY_COUNT }, (_, i) => g.countries[i].owner);
    assert.deepEqual(owners, a.owners, `seed ${a.seed}, ${a.players} players`);
    assert.equal(g.turn, a.turn, `seed ${a.seed}, ${a.players} players: first player`);
    assert.equal(g.countries.reduce((n, c) => n + c.armies, 0), 50);
    assert.equal(g.players.reduce((n, p) => n + g.countriesOf(p.seat).length, 0), 50);
  }
});

test('secret missions: the original server assigns the same ones', () => {
  for (const m of oracle.missions) {
    const g = TegGame.create(m.seed, setups(m.players), { secretMissions: true, commonMission: true });
    assert.deepEqual(Array.from({ length: COUNTRY_COUNT }, (_, i) => g.countries[i].owner), m.owners);
    assert.equal(g.turn, m.turn);
    const got = Array.from({ length: m.players }, (_, seat) => g.requestMission(seat));
    assert.deepEqual(got, m.missions, `seed ${m.seed}, ${m.players} players`);
  }
});

test('attacks: the original server\'s dice and countries, attack by attack', () => {
  for (const run of oracle.attacks) {
    const g = TegGame.create(run.seed, setups(2), {
      startArmies: run.armies[0], secondArmies: run.armies[1],
    });
    assert.deepEqual(Array.from({ length: COUNTRY_COUNT }, (_, i) => g.countries[i].owner), run.owners);
    assert.equal(g.turn, run.turn);
    for (const p of run.placements) {
      const ok = g.place(p.seat, new Map([[p.country, p.armies]]));
      assert.ok(ok, `placement ${p.phase} ${p.country}:${p.armies}`);
    }
    for (const [k, a] of run.attacks.entries()) {
      const roll = g.attack(run.turn, a.dice.src, a.dice.dst);
      assert.ok(roll, `attack ${k}`);
      const pad3 = (v: number[]) => [v[0] ?? 0, v[1] ?? 0, v[2] ?? 0];
      assert.deepEqual([roll.src, ...pad3(roll.srcDice)], [a.dice.src, ...a.dice.srcDice], `attack ${k} attacker dice`);
      assert.deepEqual([roll.dst, ...pad3(roll.dstDice)], [a.dice.dst, ...a.dice.dstDice], `attack ${k} defender dice`);
      for (const [c, [owner, armies]] of Object.entries(a.countries)) {
        assert.equal(g.countries[Number(c)].owner, owner, `attack ${k}, country ${c} owner`);
        assert.equal(g.countries[Number(c)].armies, armies, `attack ${k}, country ${c} armies`);
      }
      if (a.conquest) {
        assert.equal(g.phase, 'move');
        assert.equal(g.pendingMove?.max, a.tropas);
      }
      if (run.card && k === run.attacks.length - 1) {
        const card = g.drawCard(run.turn);
        assert.equal(card, run.card.country);
        assert.equal(g.countries[run.card.country as number].cardUsed, run.card.used);
        assert.equal(g.countries[run.card.country as number].cardOwner, run.turn);
        assert.deepEqual(g.cardsOf(run.turn), (run.enumCards ?? '').split(',').filter(Boolean).map((s) => Number(s.split(':')[0])));
      } else if (a.conquest) {
        assert.ok(g.moveAfterConquest(run.turn, 0));
        assert.equal(g.phase, 'attack');
      }
    }
  }
});

test('cards: exchange values and combinations as in common/tarjeta.cpp', () => {
  assert.deepEqual([0, 1, 2, 3, 4, 5, 6].map(cardsForExchange), [0, 4, 7, 10, 15, 20, 25]);
  assert.equal(canTradeCards('galleon', 'galleon', 'galleon'), true);
  assert.equal(canTradeCards('cannon', 'cannon', 'cannon'), true);
  assert.equal(canTradeCards('balloon', 'balloon', 'balloon'), true);
  assert.equal(canTradeCards('galleon', 'cannon', 'balloon'), true);
  assert.equal(canTradeCards('joker', 'cannon', 'cannon'), true);
  assert.equal(canTradeCards('joker', 'joker', 'joker'), true);
  assert.equal(canTradeCards('galleon', 'galleon', 'cannon'), false);
  assert.equal(canTradeCards('cannon', 'balloon', 'balloon'), false);
  assert.equal(canTradeCards('galleon', 'cannon', 'cannon'), false);
});

test('missions: the original\'s check, including the common mission', () => {
  const g = TegGame.create(1, setups(2), { secretMissions: true, commonMission: true });
  const p = g.player(0);
  // mission 3 is "Conquer Asia and 2 countries of South America" (no common mission win yet)
  p.mission = 3;
  for (let c = 0; c < COUNTRY_COUNT; c++) g.countries[c].owner = c < 20 ? 0 : 1;
  assert.equal(g.checkMission(0), false); // 20 countries and no complete Asia
  for (let c = 20; c < 30; c++) g.countries[c].owner = 0;
  for (const c of COUNTRIES.filter((x) => x.continent === 5).map((x) => x.id)) g.countries[c].owner = 0;
  // Asia complete, but only 30 countries: the common mission wins first (>= 30)
  assert.equal(g.checkMission(0), true);
  assert.equal(p.mission, 1);
  // without the common mission, the secret mission itself wins now
  const h = TegGame.create(1, setups(2), { secretMissions: true, commonMission: false });
  const q = h.player(0);
  q.mission = 3;
  for (let c = 0; c < COUNTRY_COUNT; c++) h.countries[c].owner = c < 30 ? 0 : 1;
  for (const c of COUNTRIES.filter((x) => x.continent === 5).map((x) => x.id)) h.countries[c].owner = 0;
  assert.equal(h.checkMission(0), true);
  assert.equal(q.mission, 3);
  // the port's mission text replaces the continent placeholders
  assert.match(missionName(2), /^Conquer Africa,\n5 countries of North America and\n4 countries of Europe$/);
});

test('reinforcement: 3 armies up to six countries, half above; continents and exchanges add', () => {
  const g = TegGame.create(2, setups(2));
  for (let c = 0; c < COUNTRY_COUNT; c++) g.countries[c].owner = c < 6 ? 0 : 1;
  assert.equal(g.baseReinforcement(0), 3);
  g.countries[6].owner = 0;
  assert.equal(g.baseReinforcement(0), 3); // 7/2 = 3
  g.countries[7].owner = 0;
  assert.equal(g.baseReinforcement(0), 4); // 8/2
  // all of South America (countries 0..5) is owned: its 3 armies are part of the total
  assert.equal(g.completeContinents(0) & 1, 1);
  assert.equal(g.reinforcement(0).bonus, 3);
  g.player(0).hasExchanged = true;
  g.player(0).exchanges = 2;
  assert.equal(g.reinforcement(0).exchange, 7);
});

test('fog of war: your countries and their neighbours are visible', () => {
  const g = TegGame.create(1, setups(2), { fogOfWar: true });
  for (let c = 0; c < COUNTRY_COUNT; c++) g.countries[c].owner = c === 0 ? 0 : 1;
  assert.equal(g.canSee(0, 0), true);
  assert.equal(g.canSee(0, 1), true); // country 1 borders country 0
  assert.equal(g.canSee(0, 49), false); // Japan is not next to Argentina
  assert.equal(g.canSee(1, 49), true);
});

test('regroup and the continent-bonus placement rule', () => {
  const g = TegGame.create(1, setups(2));
  g.turn = 0;
  g.phase = 'attack';
  g.roundStarter = 0;
  for (let c = 0; c < COUNTRY_COUNT; c++) g.countries[c].owner = c === 0 || c === 1 ? 0 : 1;
  g.countries[0].armies = 5;
  g.countries[1].armies = 1;
  g.countries[0].regrouped = 0;
  assert.equal(g.regroup(0, 0, 1, 3), true);
  assert.equal(g.countries[0].armies, 2);
  assert.equal(g.countries[1].armies, 4);
  assert.equal(g.countries[1].regrouped, 3);
  assert.equal(g.phase, 'regroup');
  assert.equal(g.canAttack(0, 0, 2), false);
  // ending the turn clears the regrouped markers
  g.endTurn(0);
  assert.equal(g.countries[1].regrouped, 0);

  const h = TegGame.create(1, setups(2));
  h.turn = 0;
  h.phase = 'reinforce';
  h.roundStarter = 0;
  for (let c = 0; c < COUNTRY_COUNT; c++) h.countries[c].owner = (c < 6 || c === 6) ? 0 : 1;
  for (let c = 0; c < 6; c++) h.countries[c].armies = 1;
  h.countries[6].armies = 1;
  // six countries and a complete South America: 3 base + 3 bonus = 6
  assert.equal(h.requiredArmies(0), 6);
  // the page asks checkPlacement before it sends a plan, so a refused plan keeps its armies placed
  assert.equal(h.checkPlacement(0, new Map([[6, 6]])), 'The 3 armies of South America must be placed in South America.');
  assert.equal(h.checkPlacement(0, new Map([[0, 2], [6, 4]])), 'The 3 armies of South America must be placed in South America.');
  assert.equal(h.checkPlacement(0, new Map([[0, 3], [1, 3]])), null);
  const before = h.countries.map((c) => c.armies);
  assert.equal(h.place(0, new Map([[6, 6]])), false, 'the South America bonus cannot go outside South America');
  assert.deepEqual(h.countries.map((c) => c.armies), before, 'a refused placement changes nothing');
  assert.equal(h.place(0, new Map([[0, 2], [6, 4]])), false, 'the bonus must all be in South America');
  assert.equal(h.place(0, new Map([[0, 3], [1, 3]])), true);
});

test('a whole game with robots ends and keeps the invariants', () => {
  for (const seed of [1, 2, 12345]) {
    const g = TegGame.create(seed, [
      { name: 'R0', color: 0, human: false }, { name: 'R1', color: 1, human: false },
      { name: 'R2', color: 2, human: false }, { name: 'R3', color: 3, human: false },
    ], { secretMissions: true, commonMission: true });
    const robots = [0, 1, 2, 3].map((s) => new Robot(g, s));
    let steps = 0;
    while (!g.isOver() && steps < 20000) {
      const r = robots[g.turn].step();
      if (!r) break;
      // every country that is owned has at least one army
      for (const [i, c] of g.countries.entries()) if (c.owner >= 0) assert.ok(c.armies >= 1, `seed ${seed}: country ${i}`);
      steps++;
    }
    assert.ok(g.isOver(), `seed ${seed}: the robots finished (${steps} steps, phase ${g.phase})`);
    assert.ok(g.winner !== null);
    assert.ok(g.player(g.winner).active);
  }
});
